const body = $input.item.json.body || $input.item.json;
const eventType = body.event_type || body.type;
const actions = [];
if (eventType === 'employee.onboarded' || eventType === 'employee.role_changed') {
  const userId = body.employee_id || body.user_id;
  const dept = body.department;
  const role = body.role;
  const tenantId = body.tenant_id || 'corp-default';
  const docSets = [];
  if (dept === 'engineering') docSets.push({ resource_type: 'folder', resource_id: 'engineering-docs', relation: 'viewer' });
  if (dept === 'finance') docSets.push({ resource_type: 'folder', resource_id: 'finance-docs', relation: 'viewer' });
  if (role === 'manager') docSets.push({ resource_type: 'folder', resource_id: 'management-docs', relation: 'viewer' });
  docSets.push({ resource_type: 'folder', resource_id: 'company-wide', relation: 'viewer' });
  docSets.forEach(ds => actions.push({ action: 'grant', subject_type: 'user', subject_id: userId, ...ds, tenant_id: tenantId, user_id: userId, dept, role }));
} else if (eventType === 'employee.offboarded') {
  actions.push({ action: 'revoke', subject_type: 'user', subject_id: body.employee_id, resource_type: 'user', resource_id: body.employee_id, relation: 'owner', note: 'offboarding-all' });
}
return actions.map(a => ({ json: a }));

